#### Codestral

#include "World.hpp"

namespace TunnelStrike {

World::World() : crosshair(std::make_unique<Crosshair>(*this)), shots(std::make_unique<Shots>(*this)), targets(std::make_unique<Targets>(*this)), walls(std::make_unique<Walls>(*this)), kills(0) {
    entities.push_back(crosshair.get());
    entities.push_back(shots.get());
    entities.push_back(targets.get());
    entities.push_back(walls.get());
}

void World::Tick(sf::Time delta) {
    for (auto& entity : entities) {
        entity->Tick(delta);
    }
}

void World::draw(sf::RenderTarget& target, const sf::RenderStates& states) const {
    for (const auto& entity : entities) {
        target.draw(*entity, states);
    }
}

void World::killed() {
    ++kills;
}

} // namespace TunnelStrike



#### DeepSeek-Coder-V2-Lite-Instruct

#include "World.hpp"

#include <algorithm>

#include "Entity.hpp"
#include "Main.hpp"


namespace TunnelStrike {


        World::World() : kills(0)
        {
                entities.push_back(crosshair.get());
                entities.push_back(shots.get());
                entities.push_back(targets.get());
                entities.push_back(walls.get());
        }

        void World::Tick(sf::Time delta)
        {
                for (auto& entity : entities) {
                        entity->Tick(delta);
                }
        }

        void World::draw(sf::RenderTarget& target, const sf::RenderStates& states) const
        {
                target.setView(Main::view);

                for (const auto& entity : entities) {
                        if (dynamic_cast<const Shots*>(entity)) continue; // Don't draw shots in the HUD view
                        target.draw(*entity, states);
                }

                // Draw kills in the HUD view
                auto hud = target.getDefaultView();
                hud.setViewport(sf::FloatRect(0.f, 0.f, 1.f, 1.f));
                target.setView(hud);
                Main::font.draw(target, sf::Text("Kills: " + std::to_string(kills), Main::font, 24U), { 5.0f, 5.0f });
        }

        void World::killed()
        {
                kills++;
        }


}


